  "className": "DefenseSystemTest",
  "sourceCode": "import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

/* For assertions you can use:
 - assertTrue
 - assertFalse
 - assertEquals
 - assertNotEquals
 - assertArrayEquals
 - assertThrows
 - assertNull
 - assertNotNull
 */

public class DefenseSystemTest {

   private static final double DELTA = 0.0001;

    @Test
    public void testInitialPosition() {
        // Verifica se o sistema começa na posição (0.0, 0.0)
        DefenseSystem ds = new DefenseSystem();
        assertEquals("A posição inicial X deve ser 0.", 0.0, ds.getCurrentPosX(), DELTA);
        assertEquals("A posição inicial Y deve ser 0.", 0.0, ds.getCurrentPosY(), DELTA);
    }

    @Test
    public void testMove() {
        // Verifica se mover soma corretamente os valores à posição atual
        DefenseSystem ds = new DefenseSystem();
        ds.move(5.5, -2.5);
        assertEquals("A posição X deve ser atualizada para 5.5", 5.5, ds.getCurrentPosX(), DELTA);
        assertEquals("A posição Y deve ser atualizada para -2.5", -2.5, ds.getCurrentPosY(), DELTA);
    }

    @Test
    public void testDistanceTo() {
        DefenseSystem ds = new DefenseSystem();
        // Usando o clássico triângulo 3-4-5 para testar a distância do ponto (0,0) ao (3,4)
        assertEquals("A distância para (3, 4) deve ser 5.", 5.0, ds.distanceTo(3.0, 4.0), DELTA);
    }

    @Test
    public void testIsWithinRange() {
        DefenseSystem ds = new DefenseSystem();
        // MIN_RANGE é 10.
        assertTrue("Distância de 9.9 deve estar dentro do alcance.", ds.isWithinRange(0.0, 9.9));

        // A lógica é estritamente MENOR que (<), por isso exatamente 10 é falso
        assertFalse("Distância de 10.0 não deve estar dentro do alcance (é estritamente menor).", ds.isWithinRange(0.0, 10.0));
        assertFalse("Distância de 15.0 não deve estar dentro do alcance.", ds.isWithinRange(0.0, 15.0));
    }

    @Test
    public void testFleeFromOutsideRange() {
        DefenseSystem ds = new DefenseSystem();
        // Um perigo a uma distância de 15 está fora de alcance (MIN_RANGE = 10)
        ds.fleeFrom(15.0, 0.0);

        // O sistema não se deve ter movido
        assertEquals("Não se deve mover se a ameaça estiver fora do alcance.", 0.0, ds.getCurrentPosX(), DELTA);
        assertEquals("Não se deve mover se a ameaça estiver fora do alcance.", 0.0, ds.getCurrentPosY(), DELTA);
    }

    @Test
    public void testFleeFromInsideRange() {
        DefenseSystem ds = new DefenseSystem();
        // A ameaça está em (3,4), o que dá uma distância de 5. 
        // O sistema deve afastar-se na direção oposta até atingir uma distância de segurança de 10.
        ds.fleeFrom(3.0, 4.0);

        // O sistema afasta-se exatamente 5 unidades. Como a direção era positiva, ele foge para coordenadas negativas.
        assertEquals("Nova posição X após fuga deve ser -3.0", -3.0, ds.getCurrentPosX(), DELTA);
        assertEquals("Nova posição Y após fuga deve ser -4.0", -4.0, ds.getCurrentPosY(), DELTA);

        // Verificação final de sanidade: a distância do sistema à ameaça agora tem de ser exatemente o MIN_RANGE (10)
        assertEquals("A distância final para a ameaça deve ser exatamente 10.", 10.0, ds.distanceTo(3.0, 4.0), DELTA);
    }

    @Test
    public void testFleeFrom2() {
        DefenseSystem spaceShip = new DefenseSystem();
        spaceShip.move(0, 5);
        spaceShip.fleeFrom(5, 0);
        assertEquals(-2.07, spaceShip.getCurrentPosX(), 0.01);
        assertEquals( 7.07, spaceShip.getCurrentPosY(), 0.01);
    }

}
