  "sourceCode": "import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

/* For assertions you can use:
 - assertTrue
 - assertFalse
 - assertEquals
 - assertNotEquals
 - assertArrayEquals
 - assertThrows
 - assertNull
 - assertNotNull
 */

public class ReactorLogTest {

   @Test
    public void testCurrentTemperature() {
        ReactorLog log = new ReactorLog(500);
        assertEquals("Initial temperature should be 500", 500, log.getCurrentTemperature());

        log.logTemperature(600);
        assertEquals("Current temperature should update to 600", 600, log.getCurrentTemperature());
    }

    @Test
    public void testMaximumTemperature() {
        ReactorLog log = new ReactorLog(500);
        log.logTemperature(800); // Max is here
        log.logTemperature(600);

        // This will hit the `if (temperature > max)` block inside getMaximumTemperature()
        assertEquals("Max temperature should be 800", 800, log.getMaximumTemperature());

        // Add a new max at the end of the list
        log.logTemperature(900);
        assertEquals("New max temperature should be 900", 900, log.getMaximumTemperature());
    }

    @Test
    public void testLogsSinceMaxTemperature() {
        ReactorLog log = new ReactorLog(500); // index 0
        assertEquals("0 logs since max because it's the only entry", 0, log.logsSinceMaxTemperature());

        log.logTemperature(800); // index 1 (Current max)
        log.logTemperature(600); // index 2
        log.logTemperature(700); // index 3

        // Array size is 4. Max is at index 1. logs = 4 - 1 - 1 = 2
        assertEquals(2, log.logsSinceMaxTemperature());

        // Add a duplicate max to test the `if (temperatures.get(i) >= max)` block
        log.logTemperature(800); // index 4 (New max index because of >=)
        log.logTemperature(100); // index 5

        // Array size is 6. Latest max is at index 4. logs = 6 - 4 - 1 = 1
        assertEquals(1, log.logsSinceMaxTemperature());
    }
}
