tam 4.0 para ficar seguro)\n        // O sistema deve mover-se na dire\u00e7\u00e3o oposta (Eixo X negativo) e parar exatamente em (-4.0, 0.0)\n        system.fleeFrom(6.0, 0.0);\n        assertEquals(-4.0, system.getCurrentPosX(), 0.0001);\n        assertEquals(0.0, system.getCurrentPosY(), 0.0001);\n    }\n    @Test\n    public void testFleeFrom2() {\n        DefenseSystem spaceShip = new DefenseSystem();\n        spaceShip.move(0, 5);\n        spaceShip.fleeFrom(5, 0);\n        assertEquals(-2.07, spaceShip.getCurrentPosX(), 0.01);\n        assertEquals( 7.07, spaceShip.getCurrentPosY(), 0.01);\n    }\n\n}\n",
