  "sourceCode": "import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

/* For assertions you can use:
 - assertTrue
 - assertFalse
 - assertEquals
 - assertNotEquals
 - assertArrayEquals
 - assertThrows
 - assertNull
 - assertNotNull
 */

public class DefenseSystemTest {

   @Test
    public void test() {
        // Teste 1: Estado inicial (deve começar na posição 0.0, 0.0)
        DefenseSystem system = new DefenseSystem();
        assertEquals(0.0, system.getCurrentPosX(), 0.0001);
        assertEquals(0.0, system.getCurrentPosY(), 0.0001);

        // Teste 2: Movimento básico do sistema
        system.move(5.5, -2.0);
        assertEquals(5.5, system.getCurrentPosX(), 0.0001);
        assertEquals(-2.0, system.getCurrentPosY(), 0.0001);

        // Reposicionar o sistema em (0,0) para simplificar os próximos testes geométricos
        system.move(-5.5, 2.0);

        // Teste 3: Cálculo de distância (Triângulo retângulo 3-4-5)
        double distance = system.distanceTo(3.0, 4.0);
        assertEquals(5.0, distance, 0.0001);

        // Teste 4: Verificação de alcance (MIN_RANGE é 10)
        assertTrue(system.isWithinRange(3.0, 4.0));   // Distância 5.0 está dentro do alcance (< 10)
        assertFalse(system.isWithinRange(0.0, 10.0)); // Distância 10.0 está no limite exato, logo dá false
        assertFalse(system.isWithinRange(0.0, 15.0)); // Distância 15.0 está completamente fora

        // Teste 5: Tentar fugir de uma ameaça fora de alcance (Não deve mover-se)
        system.fleeFrom(0.0, 15.0);
        assertEquals(0.0, system.getCurrentPosX(), 0.0001);
        assertEquals(0.0, system.getCurrentPosY(), 0.0001);

        // Teste 6: Fugir de uma ameaça dentro de alcance
        // Ameaça colocada em (6.0, 0.0) -> Distância é 6.0 (está muito perto, faltam 4.0 para ficar seguro)
        // O sistema deve mover-se na direção oposta (Eixo X negativo) e parar exatamente em (-4.0, 0.0)
        system.fleeFrom(6.0, 0.0);
        assertEquals(-4.0, system.getCurrentPosX(), 0.0001);
        assertEquals(0.0, system.getCurrentPosY(), 0.0001);
    }
}
