  "sourceCode": "import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

/* For assertions you can use:
 - assertTrue
 - assertFalse
 - assertEquals
 - assertNotEquals
 - assertArrayEquals
 - assertThrows
 - assertNull
 - assertNotNull
 */

public class ReactorLogTest {

    @Test
    public void testInitialTemperatureIsCurrentTemperature() {
        ReactorLog log = new ReactorLog(100);

        assertEquals(100, log.getCurrentTemperature());
    }

    @Test
    public void testLogTemperatureUpdatesCurrentTemperature() {
        ReactorLog log = new ReactorLog(100);

        log.logTemperature(120);

        assertEquals(120, log.getCurrentTemperature());
    }

    @Test
    public void testGetMaximumTemperatureInitially() {
        ReactorLog log = new ReactorLog(90);

        assertEquals(90, log.getMaximumTemperature());
    }

    @Test
    public void testGetMaximumTemperatureAfterSeveralLogs() {
        ReactorLog log = new ReactorLog(100);

        log.logTemperature(120);
        log.logTemperature(110);
        log.logTemperature(150);
        log.logTemperature(130);

        assertEquals(150, log.getMaximumTemperature());
    }

    @Test
    public void testGetMaximumTemperatureWithNegativeValues() {
        ReactorLog log = new ReactorLog(-10);

        log.logTemperature(-30);
        log.logTemperature(-5);
        log.logTemperature(-20);

        assertEquals(-5, log.getMaximumTemperature());
    }

    @Test
    public void testLogsSinceMaxTemperatureWhenMaxIsCurrent() {
        ReactorLog log = new ReactorLog(100);

        log.logTemperature(120);
        log.logTemperature(150);

        assertEquals(0, log.logsSinceMaxTemperature());
    }

    @Test
    public void testLogsSinceMaxTemperatureWhenMaxIsInThePast() {
        ReactorLog log = new ReactorLog(100);

        log.logTemperature(150);
        log.logTemperature(130);
        log.logTemperature(120);

        assertEquals(2, log.logsSinceMaxTemperature());
    }

    @Test
    public void testLogsSinceMaxTemperatureWithRepeatedMaximum() {
        ReactorLog log = new ReactorLog(100);

        log.logTemperature(150);
        log.logTemperature(130);
        log.logTemperature(150);
        log.logTemperature(120);

        assertEquals(1, log.logsSinceMaxTemperature());
    }

    @Test
    public void testLogsSinceMaxTemperatureInitially() {
        ReactorLog log = new ReactorLog(100);

        assertEquals(0, log.logsSinceMaxTemperature());
    }

}
