    @Test
    public void testInicializacaoETemperaturaAtual() {
        // Inicializa o reator com 150 graus
        ReactorLog log = new ReactorLog(150);

        assertEquals(150, log.getCurrentTemperature());

        // Adiciona uma nova temperatura e checa se atualizou
        log.logTemperature(180);
        assertEquals(180, log.getCurrentTemperature());
    }

    @Test
    public void testPegarTemperaturaMaxima() {
        // Inicializa com 100
        ReactorLog log = new ReactorLog(100);

        log.logTemperature(250); // Maior valor
        log.logTemperature(200);
        log.logTemperature(150);

        assertEquals(250, log.getMaximumTemperature());
    }

    @Test
    public void testLogsSinceMaxTemperatureWithMaxTwice() {
        ReactorLog log = new ReactorLog(324);
        log.logTemperature(345);
        log.logTemperature(315);
        log.logTemperature(345);
        assertEquals(0, log.logsSinceMaxTemperature());
    }

}
