import org.junit.Test;
import static org.junit.Assert.*;

/* For assertions you can use:
 - assertTrue
 - assertFalse
 - assertEquals
 - assertNotEquals
 - assertArrayEquals
 - assertThrows
 - assertNull
 - assertNotNull
 */

public class ReactorLogTest {

    @Test
    public void testConstructorAndCurrentTemperature() {
        // Verifica se o log inicializa corretamente com a primeira temperatura
        ReactorLog log = new ReactorLog(100);
        assertEquals("A temperatura atual deve ser igual à inicial.", 100, log.getCurrentTemperature());
    }

    @Test
    public void testLogTemperature() {
        // Verifica se novas temperaturas são adicionadas ao log e passam a ser a atual
        ReactorLog log = new ReactorLog(100);
        log.logTemperature(120);
        log.logTemperature(95);

        assertEquals("A temperatura atual deve ser a última registada (95).", 95, log.getCurrentTemperature());
    }

    @Test
    public void testGetMaximumTemperature() {
        // Verifica se encontra corretamente o valor máximo
        ReactorLog log = new ReactorLog(100);
        log.logTemperature(150); // Novo máximo
        log.logTemperature(120);
        log.logTemperature(150); // Empate
        log.logTemperature(90);

        assertEquals("A temperatura máxima registada deve ser 150.", 150, log.getMaximumTemperature());
    }

    @Test
    public void testLogsSinceMaxTemperature_MaxAtBeginning() {
        // Testa o cenário onde o máximo foi logo a primeira leitura
        ReactorLog log = new ReactorLog(200);
        log.logTemperature(190);
        log.logTemperature(180);
        // Temos [200, 190, 180]. O máximo é o índice 0. Passaram 2 logs.

        assertEquals("Devem ter passado 2 logs desde o máximo.", 2, log.logsSinceMaxTemperature());
    }

    @Test
    public void testLogsSinceMaxTemperature_MaxAtEnd() {
        // Testa o cenário onde a leitura mais recente é o máximo
        ReactorLog log = new ReactorLog(100);
        log.logTemperature(150);
        log.logTemperature(200);
        // O máximo (200) acabou de acontecer, logo passaram 0 logs.

        assertEquals("Devem ter passado 0 logs pois o máximo acabou de ser registado.", 0, log.logsSinceMaxTemperature());
    }

    @Test
    public void testLogsSinceMaxTemperatureWithMaxTwice() {
        ReactorLog log = new ReactorLog(324);
        log.logTemperature(345);
        log.logTemperature(315);
        log.logTemperature(345);
        assertEquals(0, log.logsSinceMaxTemperature());
    }

}
