  "sourceCode": "import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

/* For assertions you can use:
 - assertTrue
 - assertFalse
 - assertEquals
 - assertNotEquals
 - assertArrayEquals
 - assertThrows
 - assertNull
 - assertNotNull
 */

public class GreenHouseTest {

    // Plantar muda estado de EMPTY para GROWING
    @Test
    public void testPlantChangesStateToGrowing() {
        GreenHouse gh = new GreenHouse(3);
        gh.plant(0);
        assertEquals(GreenHouse.Plant.GROWING, gh.getPlantInfo()[0]);
    }

    // Regar muda estado de GROWING para READY
    @Test
    public void testWaterChangesStateToReady() {
        GreenHouse gh = new GreenHouse(3);
        gh.plant(0);
        gh.water(0);
        assertEquals(GreenHouse.Plant.READY, gh.getPlantInfo()[0]);
    }

