    "sourceCode": "import java.util.*;\nimport org.junit.Test;\nimport static org.junit.Assert.*;\n\n/* For assertions you can use:\n - assertTrue\n - assertFalse\n - assertEquals\n - assertNotEquals\n - assertArrayEquals\n - assertThrows\n - assertNull\n - assertNotNull\n */\n\npublic class ReactorLogTest {\n\n    @Test\n    public void testEstadoInicialELogs() {\n        ReactorLog log = new ReactorLog(150);\n        \n        assertEquals(150, log.getCurrentTemperature());\n        assertEquals(150, log.getMaximumTemperature());\n        assertEquals(0, log.logsSinceMaxTemperature());\n        \n        log.logTemperature(160);\n        assertEquals(160, log.getCurrentTemperature());\n        assertEquals(160, log.getMaximumTemperature());\n        assertEquals(0, log.logsSinceMaxTemperature());\n    }\n\n    @Test\n    public void testTemperaturaMaximaEContagem() {\n        ReactorLog log = new ReactorLog(100);\n        log.logTemperature(250); \n        log.logTemperature(200); \n        log.logTemperature(180); \n        \n        assertEquals(180, log.getCurrentTemperature());\n        assertEquals(250, log.getMaximumTemperature());\n        assertEquals(2, log.logsSinceMaxTemperature());\n    }\n\n    @Test\n    public void testContagemComMaximoRepetido() {\n        ReactorLog log = new ReactorLog(300); \n        log.logTemperature(150);\n        log.logTemperature(300); \n        log.logTemperature(200);\n        \n        assertEquals(300, log.getMaximumTemperature());\n        assertEquals(1, log.logsSinceMaxTemperature());\n    }\n\n    @Test\n    public void testMaximoNoFinal() {\n        ReactorLog log = new ReactorLog(100);\n        log.logTemperature(120);\n        log.logTemperature(140);\n        \n        assertEquals(140, log.getMaximumTemperature());\n        assertEquals(0, log.logsSinceMaxTemperature());\n    }\n\n}\n",
