import org.junit.Test;
import static org.junit.Assert.*;

/* For assertions you can use:
 - assertTrue
 - assertFalse
 - assertEquals
 - assertNotEquals
 - assertArrayEquals
 - assertThrows
 - assertNull
 - assertNotNull
 */

public class ReactorLogTest {

    @Test
    public void test() {
        // Teste 1: Estado inicial com apenas a temperatura de arranque
        ReactorLog log = new ReactorLog(150);
        assertEquals(150, log.getCurrentTemperature());
        assertEquals(150, log.getMaximumTemperature());
        assertEquals(0, log.logsSinceMaxTemperature());

        // Teste 2: Adicionar novas temperaturas e validar o estado atual e máximo
        log.logTemperature(180);
        log.logTemperature(160);
        assertEquals(160, log.getCurrentTemperature());
        assertEquals(180, log.getMaximumTemperature());

        // Teste 3: Validar a quantidade de logs registados após o pico de temperatura
        // Histórico atual: [150, 180, 160] -> O pico foi 180. Só o 160 foi registado depois.
        assertEquals(1, log.logsSinceMaxTemperature());

        // Teste 4: Adicionar mais um registo abaixo do pico anterior
        log.logTemperature(140);
        // Histórico atual: [150, 180, 160, 140] -> Elementos após o pico: 2 (o 160 e o 140)
        assertEquals(2, log.logsSinceMaxTemperature());

        // Teste 5: Validar comportamento com picos duplicados (valores iguais à máxima)
        // A lógica do teu código usa o operador `>=` no loop, o que significa que ele vai
        // atualizar o ponto de referência para a máxima mais recente que encontrar.
        log.logTemperature(180); // Novo pico igual ao anterior
        log.logTemperature(170); // Apenas este registo vem após o novo pico

        // Histórico atual: [150, 180, 160, 140, 180, 170]
        assertEquals(180, log.getMaximumTemperature());
        assertEquals(1, log.logsSinceMaxTemperature()); // Deve dar 1 por causa do 170
    }

}
