  "className": "KitchenTest",
  "sourceCode": "import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

/* For assertions you can use:
 - assertTrue
 - assertFalse
 - assertEquals
 - assertNotEquals
 - assertArrayEquals
 - assertThrows
 - assertNull
 - assertNotNull
 */

public class KitchenTest {

    @Test
    public void testAdicionarIngredientes() {
        Kitchen kitchen = new Kitchen();

        // Ingrediente não existente deve retornar 0
        assertEquals(0, kitchen.getIngredientAmount("Arroz"));

        // Adicionando pela primeira vez
        kitchen.addIngredient("Arroz", 500);
        assertEquals(500, kitchen.getIngredientAmount("Arroz"));

        // Somando ao valor existente
        kitchen.addIngredient("Arroz", 250);
        assertEquals(750, kitchen.getIngredientAmount("Arroz"));
    }

    @Test
    public void testRemoverIngredientesComSucesso() {
        Kitchen kitchen = new Kitchen();
        kitchen.addIngredient("Feijão", 1000);

        kitchen.removeIngredient("Feijão", 300);
        assertEquals(700, kitchen.getIngredientAmount("Feijão"));
    }

    @Test
    public void testRemoverIngredientesMaisDoQueODisponivel() {
        Kitchen kitchen = new Kitchen();
        kitchen.addIngredient("Feijão", 200);

        // Deve lançar IllegalArgumentException por falta de estoque
        assertThrows(IllegalArgumentException.class, () -> {
            kitchen.removeIngredient("Feijão", 500);
        });
    }

    @Test
    public void testCookFailRemovesNoIngredients() {
        Kitchen kitchen = new Kitchen();
        kitchen.addIngredient("tofu", 400);
        kitchen.addIngredient("soy sauce", 50);
        kitchen.addIngredient("rice", 10);
        kitchen.addIngredient("onion", 1);

        Map<String, Integer> recipe = Map.of(
            "tofu", 400,
            "soy sauce", 20,
            "rice", 200,
            "onion", 1
        );

        // If you're hungry now, here's the full recipe:
        // https://thewoksoflife.com/teriyaki-tofu
        // Be sure to get enough rice tho

        try {
            kitchen.cookRecipe(recipe);
        } catch (IllegalArgumentException ignored) {}

        assertEquals(400, kitchen.getIngredientAmount("tofu"));
        assertEquals(50, kitchen.getIngredientAmount("soy sauce"));
        assertEquals(10, kitchen.getIngredientAmount("rice"));
        assertEquals(1, kitchen.getIngredientAmount("onion"));
    }

}
