  "sourceCode": "import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

/* For assertions you can use:
 - assertTrue
 - assertFalse
 - assertEquals
 - assertNotEquals
 - assertArrayEquals
 - assertThrows
 - assertNull
 - assertNotNull
 */

public class KitchenTest {

    @Test
    public void testGetIngredientAmountReturnsZeroWhenAbsent() {
        Kitchen kitchen = new Kitchen();
        assertEquals("Missing ingredient should return 0", 0, kitchen.getIngredientAmount("flour"));
    }

    @Test
    public void testAddIngredientAccumulates() {
        Kitchen kitchen = new Kitchen();
        kitchen.addIngredient("salt", 3);
        kitchen.addIngredient("salt", 7);
        assertEquals("Adding twice should accumulate correctly", 10, kitchen.getIngredientAmount("salt"));
    }

    @Test
    public void testRemoveIngredientDecreasesAmount() {
        Kitchen kitchen = new Kitchen();
        kitchen.addIngredient("milk", 10);
        kitchen.removeIngredient("milk", 4);
        assertEquals("Removing should decrease the amount", 6, kitchen.getIngredientAmount("milk"));
    }

    @Test
    public void testCookRecipeDeductsIngredients() {
        Kitchen kitchen = new Kitchen();
        kitchen.addIngredient("flour", 10);
        kitchen.addIngredient("eggs", 4);

        Map<String, Integer> recipe = new HashMap<>();
        recipe.put("flour", 5);
        recipe.put("eggs", 2);

        kitchen.cookRecipe(recipe);

        assertEquals("Flour should be reduced after cooking", 5, kitchen.getIngredientAmount("flour"));
        assertEquals("Eggs should be reduced after cooking", 2, kitchen.getIngredientAmount("eggs"));
    }

}
