    @Test
    public void testAdicionarIngredientes() {
        Kitchen kitchen = new Kitchen();

        // Ingrediente não existente deve retornar 0
        assertEquals(0, kitchen.getIngredientAmount("Arroz"));

        // Adicionando pela primeira vez
        kitchen.addIngredient("Arroz", 500);
        assertEquals(500, kitchen.getIngredientAmount("Arroz"));

        // Somando ao valor existente
        kitchen.addIngredient("Arroz", 250);
        assertEquals(750, kitchen.getIngredientAmount("Arroz"));
    }

    @Test
    public void testRemoverIngredientesComSucesso() {
        Kitchen kitchen = new Kitchen();
        kitchen.addIngredient("Feijão", 1000);

        kitchen.removeIngredient("Feijão", 300);
        assertEquals(700, kitchen.getIngredientAmount("Feijão"));
    }

    @Test
    public void testRemoverIngredientesMaisDoQueODisponivel() {
        Kitchen kitchen = new Kitchen();
        kitchen.addIngredient("Feijão", 200);

        // Deve lançar IllegalArgumentException por falta de estoque
        assertThrows(IllegalArgumentException.class, () -> {
            kitchen.removeIngredient("Feijão", 500);
        });
    }

}
