import org.junit.Test;
import static org.junit.Assert.*;

/* For assertions you can use:
 - assertTrue
 - assertFalse
 - assertEquals
 - assertNotEquals
 - assertArrayEquals
 - assertThrows
 - assertNull
 - assertNotNull
 */

public class KitchenTest {

    @Test
    public void testIngredientStartsAtZero() {
        Kitchen kitchen = new Kitchen();

        assertEquals(0, kitchen.getIngredientAmount("flour"));
    }

    @Test
    public void testAddIngredient() {
        Kitchen kitchen = new Kitchen();

        kitchen.addIngredient("flour", 5);

        assertEquals(5, kitchen.getIngredientAmount("flour"));
    }

    @Test
    public void testAddIngredientTwice() {
        Kitchen kitchen = new Kitchen();

        kitchen.addIngredient("flour", 5);
        kitchen.addIngredient("flour", 3);

        assertEquals(8, kitchen.getIngredientAmount("flour"));
    }

    @Test
    public void testRemoveIngredient() {
        Kitchen kitchen = new Kitchen();

        kitchen.addIngredient("sugar", 10);
        kitchen.removeIngredient("sugar", 4);

        assertEquals(6, kitchen.getIngredientAmount("sugar"));
    }

    @Test
    public void testRemoveIngredientNotEnoughThrowsException() {
        Kitchen kitchen = new Kitchen();

        kitchen.addIngredient("salt", 2);

        assertThrows(IllegalArgumentException.class, () -> {
            kitchen.removeIngredient("salt", 5);
        });
    }

    @Test
    public void testCookRecipeSuccessfully() {
        Kitchen kitchen = new Kitchen();

        kitchen.addIngredient("flour", 10);
        kitchen.addIngredient("sugar", 5);

        Map<String, Integer> recipe = new HashMap<>();
        recipe.put("flour", 4);
        recipe.put("sugar", 2);

        kitchen.cookRecipe(recipe);

        assertEquals(6, kitchen.getIngredientAmount("flour"));
        assertEquals(3, kitchen.getIngredientAmount("sugar"));
    }

    @Test
    public void testCookRecipeNotEnoughIngredientThrowsException() {
        Kitchen kitchen = new Kitchen();

        kitchen.addIngredient("flour", 10);
        kitchen.addIngredient("sugar", 1);

        Map<String, Integer> recipe = new HashMap<>();
        recipe.put("flour", 4);
        recipe.put("sugar", 2);

        assertThrows(IllegalArgumentException.class, () -> {
            kitchen.cookRecipe(recipe);
        });
    }

    @Test
    public void testCookRecipeDoesNotRemoveAnythingIfIngredientMissing() {
        Kitchen kitchen = new Kitchen();

        kitchen.addIngredient("flour", 10);
        kitchen.addIngredient("sugar", 1);

        Map<String, Integer> recipe = new HashMap<>();
        recipe.put("flour", 4);
        recipe.put("sugar", 2);

        try {
            kitchen.cookRecipe(recipe);
        } catch (IllegalArgumentException e) {
            // expected
        }

        assertEquals(10, kitchen.getIngredientAmount("flour"));
        assertEquals(1, kitchen.getIngredientAmount("sugar"));
    }

    @Test
    public void testCookEmptyRecipeDoesNothing() {
        Kitchen kitchen = new Kitchen();

        kitchen.addIngredient("flour", 10);

        Map<String, Integer> recipe = new HashMap<>();

        kitchen.cookRecipe(recipe);

        assertEquals(10, kitchen.getIngredientAmount("flour"));
    }
}
