  "sourceCode": "import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

/* For assertions you can use:
 - assertTrue
 - assertFalse
 - assertEquals
 - assertNotEquals
 - assertArrayEquals
 - assertThrows
 - assertNull
 - assertNotNull
 */

public class CryoSleepTest {


    @Test
    public void startsFrozenWhenDaysArePositive() {
        CryoSleep cryoSleep = new CryoSleep(3);

        assertTrue(cryoSleep.isFrozen());
    }

    @Test
    public void doesNotStartFrozenWhenDaysAreZero() {
        CryoSleep cryoSleep = new CryoSleep(0);

        assertFalse(cryoSleep.isFrozen());
    }

    @Test
    public void remainsFrozenBeforeAllDaysPass() {
        CryoSleep cryoSleep = new CryoSleep(2);

        cryoSleep.dayPassed();

        assertTrue(cryoSleep.isFrozen());
    }

    @Test
    public void stopsBeingFrozenAfterAllDaysPass() {
        CryoSleep cryoSleep = new CryoSleep(2);

        cryoSleep.dayPassed();
        cryoSleep.dayPassed();

        assertFalse(cryoSleep.isFrozen());
    }

    @Test
    public void staysNotFrozenAfterCryoSleepEnds() {
        CryoSleep cryoSleep = new CryoSleep(1);

        cryoSleep.dayPassed();
        cryoSleep.dayPassed();

        assertFalse(cryoSleep.isFrozen());
    }
}
