  "sourceCode": "import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

/* For assertions you can use:
 - assertTrue
 - assertFalse
 - assertEquals
 - assertNotEquals
 - assertArrayEquals
 - assertThrows
 - assertNull
 - assertNotNull
 */

public class GreenHouseTest {

    @Test
    public void testConstructorStartsEmpty() {
        GreenHouse gh = new GreenHouse(3);

        GreenHouse.Plant[] expected = {
            GreenHouse.Plant.EMPTY,
            GreenHouse.Plant.EMPTY,
            GreenHouse.Plant.EMPTY
        };

        assertArrayEquals(expected, gh.getPlantInfo());
    }

    @Test
    public void testPlantValidIndex() {
        GreenHouse gh = new GreenHouse(2);

        gh.plant(0);

        assertEquals(GreenHouse.Plant.GROWING, gh.getPlantInfo()[0]);
    }

    @Test
    public void testPlantInvalidIndexThrowsException() {
        GreenHouse gh = new GreenHouse(2);

        assertThrows(IllegalArgumentException.class, () -> {
            gh.plant(-1);
        });

        assertThrows(IllegalArgumentException.class, () -> {
            gh.plant(2);
        });
    }

    @Test
    public void testPlantAlreadyOccupiedThrowsException() {
        GreenHouse gh = new GreenHouse(2);

        gh.plant(0);

        assertThrows(IllegalStateException.class, () -> {
            gh.plant(0);
        });
    }

    @Test
    public void testWaterGrowingPlantBecomesReady() {
        GreenHouse gh = new GreenHouse(2);

        gh.plant(0);
        gh.water(0);

        assertEquals(GreenHouse.Plant.READY, gh.getPlantInfo()[0]);
    }

    @Test
    public void testWaterInvalidIndexThrowsException() {
        GreenHouse gh = new GreenHouse(2);

        assertThrows(IllegalArgumentException.class, () -> {
            gh.water(-1);
        });

        assertThrows(IllegalArgumentException.class, () -> {
            gh.water(2);
        });
    }

    @Test
    public void testWaterEmptyDoesNothing() {
        GreenHouse gh = new GreenHouse(2);

        gh.water(0);

        assertEquals(GreenHouse.Plant.EMPTY, gh.getPlantInfo()[0]);
    }

    @Test
    public void testHarvestReadyPlantBecomesEmpty() {
        GreenHouse gh = new GreenHouse(2);

        gh.plant(0);
        gh.water(0);
        gh.harvest(0);

        assertEquals(GreenHouse.Plant.EMPTY, gh.getPlantInfo()[0]);
    }

    @Test
    public void testHarvestInvalidIndexThrowsException() {
        GreenHouse gh = new GreenHouse(2);

        assertThrows(IllegalArgumentException.class, () -> {
            gh.harvest(-1);
        });

        assertThrows(IllegalArgumentException.class, () -> {
            gh.harvest(2);
        });
    }

    @Test
    public void testHarvestNotReadyThrowsException() {
        GreenHouse gh = new GreenHouse(2);

        gh.plant(0);

        assertThrows(IllegalStateException.class, () -> {
            gh.harvest(0);
        });
    }

    @Test
    public void testAutomaticCoversAllPlantStates() {
        GreenHouse gh = new GreenHouse(4);

        GreenHouse.Plant[] plants = {
            GreenHouse.Plant.EMPTY,
            GreenHouse.Plant.GROWING,
            GreenHouse.Plant.READY,
            GreenHouse.Plant.DEAD
        };

        gh.setPlantInfo(plants);
        gh.automatic();

        GreenHouse.Plant[] expected = {
            GreenHouse.Plant.GROWING,
            GreenHouse.Plant.READY,
            GreenHouse.Plant.EMPTY,
            GreenHouse.Plant.EMPTY
        };

        assertArrayEquals(expected, gh.getPlantInfo());
    }

    @Test
    public void testSetPlantInfo() {
        GreenHouse gh = new GreenHouse(2);

        GreenHouse.Plant[] plants = {
            GreenHouse.Plant.DEAD,
            GreenHouse.Plant.READY
        };

        gh.setPlantInfo(plants);

        assertArrayEquals(plants, gh.getPlantInfo());
    }

}
