  "className": "KitchenTest",
  "sourceCode": "import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

/* For assertions you can use:
 - assertTrue
 - assertFalse
 - assertEquals
 - assertNotEquals
 - assertArrayEquals
 - assertThrows
 - assertNull
 - assertNotNull
 */

public class KitchenTest {

    @Test
    public void testGetIngredientAmountEmpty() {
        // Verifica se uma cozinha nova devolve 0 para qualquer ingrediente
        Kitchen kitchen = new Kitchen();
        assertEquals("A cozinha deve devolver 0 para ingredientes não adicionados.", 
                     0, kitchen.getIngredientAmount("Sugar"));
    }

    @Test
    public void testAddIngredient() {
        Kitchen kitchen = new Kitchen();

        // Adiciona pela primeira vez
        kitchen.addIngredient("Flour", 100);
        assertEquals("A quantidade inicial deve ser 100.", 100, kitchen.getIngredientAmount("Flour"));

        // Adiciona mais ao ingrediente existente
        kitchen.addIngredient("Flour", 50);
        assertEquals("A quantidade total deve somar as adições (100 + 50).", 150, kitchen.getIngredientAmount("Flour"));
    }

    @Test
    public void testRemoveIngredientSuccess() {
        Kitchen kitchen = new Kitchen();
        kitchen.addIngredient("Salt", 10);

        // Remove uma parte
        kitchen.removeIngredient("Salt", 4);
        assertEquals("Devem sobrar 6 unidades de Sal.", 6, kitchen.getIngredientAmount("Salt"));
    }

    @Test
    public void testRemoveIngredientNotEnough() {
        Kitchen kitchen = new Kitchen();
        kitchen.addIngredient("Salt", 5);

        // Tenta remover mais do que o que existe
        assertThrows("Deve lançar exceção ao tentar remover mais quantidade do que a disponível.",
                     IllegalArgumentException.class, () -> kitchen.removeIngredient("Salt", 10));
    }

    @Test
    public void testCookRecipeSuccess() {
        Kitchen kitchen = new Kitchen();
        kitchen.addIngredient("Eggs", 4);
        kitchen.addIngredient("Flour", 200);
        kitchen.addIngredient("Sugar", 50); // Ingrediente extra que não vai ser usado

        // Cria a receita
        Map<String, Integer> recipe = new HashMap<>();
        recipe.put("Eggs", 2);
        recipe.put("Flour", 100);

        // Cozinha a receita
        kitchen.cookRecipe(recipe);

        // Verifica se os ingredientes foram deduzidos corretamente
        assertEquals("Devem sobrar 2 ovos.", 2, kitchen.getIngredientAmount("Eggs"));
        assertEquals("Devem sobrar 100 de farinha.", 100, kitchen.getIngredientAmount("Flour"));
        assertEquals("O açúcar não deve ser alterado.", 50, kitchen.getIngredientAmount("Sugar"));
    }

    @Test
    public void testCookFailRemovesNoIngredients() {
        Kitchen kitchen = new Kitchen();
        kitchen.addIngredient("tofu", 400);
        kitchen.addIngredient("soy sauce", 50);
        kitchen.addIngredient("rice", 10);
        kitchen.addIngredient("onion", 1);

        Map<String, Integer> recipe = Map.of(
            "tofu", 400,
            "soy sauce", 20,
            "rice", 200,
            "onion", 1
        );

        // If you're hungry now, here's the full recipe:
        // https://thewoksoflife.com/teriyaki-tofu
        // Be sure to get enough rice tho

        try {
            kitchen.cookRecipe(recipe);
        } catch (IllegalArgumentException ignored) {}

        assertEquals(400, kitchen.getIngredientAmount("tofu"));
        assertEquals(50, kitchen.getIngredientAmount("soy sauce"));
        assertEquals(10, kitchen.getIngredientAmount("rice"));
        assertEquals(1, kitchen.getIngredientAmount("onion"));
    }

}
