  "sourceCode": "import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

/* For assertions you can use:
 - assertTrue
 - assertFalse
 - assertEquals
 - assertNotEquals
 - assertArrayEquals
 - assertThrows
 - assertNull
 - assertNotNull
 */

public class GreenHouseTest {

    @Test
    public void testCicloDeVidaDeUmaPlantaComSucesso() {
        GreenHouse gh = new GreenHouse(1);

        // 1. Plantar -> Deve ir para GROWING
        gh.plant(0);
        assertEquals(GreenHouse.Plant.GROWING, gh.getPlantInfo()[0]);

        // 2. Regar -> Deve ir para READY
        gh.water(0);
        assertEquals(GreenHouse.Plant.READY, gh.getPlantInfo()[0]);

        // 3. Colher -> Deve voltar para EMPTY
        gh.harvest(0);
        assertEquals(GreenHouse.Plant.EMPTY, gh.getPlantInfo()[0]);
    }

    @Test
    public void testAutomatic() {
        GreenHouse gh = new GreenHouse(4);

        // Estado inicial misto para testar todos os ramos do switch
        GreenHouse.Plant[] estadoInicial = {
            GreenHouse.Plant.EMPTY,   // Deve virar GROWING
            GreenHouse.Plant.GROWING, // Deve ser regada e virar READY
            GreenHouse.Plant.READY,   // Deve ser colhida e virar EMPTY
            GreenHouse.Plant.DEAD     // Deve ser limpa e virar EMPTY
        };
        gh.setPlantInfo(estadoInicial);

        // Executa a automação da estufa
        gh.automatic();

        // Criamos um novo array isolado para validar o resultado esperado
        GreenHouse.Plant[] estadoEsperado = {
            GreenHouse.Plant.GROWING,
            GreenHouse.Plant.READY,
            GreenHouse.Plant.EMPTY,
            GreenHouse.Plant.EMPTY
        };

        assertArrayEquals(estadoEsperado, gh.getPlantInfo());
    }

}
"
