public class KitchenTest {

    @Test
    public void testAdicionarEObterIngredientes() {
        Kitchen kitchen = new Kitchen();

        assertEquals(0, kitchen.getIngredientAmount("Ovo"));

        kitchen.addIngredient("Ovo", 3);
        assertEquals(3, kitchen.getIngredientAmount("Ovo"));

        kitchen.addIngredient("Ovo", 2);
        assertEquals(5, kitchen.getIngredientAmount("Ovo"));
    }

    @Test
    public void testRemoverIngredientesComSucesso() {
        Kitchen kitchen = new Kitchen();
        kitchen.addIngredient("Leite", 1000);

        kitchen.removeIngredient("Leite", 400);
        assertEquals(600, kitchen.getIngredientAmount("Leite"));
    }

    @Test
    public void testRemoverIngredientesInsuficientes() {
        Kitchen kitchen = new Kitchen();
        kitchen.addIngredient("Leite", 200);

        assertThrows(IllegalArgumentException.class, () -> kitchen.removeIngredient("Leite", 300));
    }

    @Test
    public void testCozinharReceitaComSucesso() {
        Kitchen kitchen = new Kitchen();
        kitchen.addIngredient("Farinha", 500);
        kitchen.addIngredient("Açúcar", 200);

        Map<String, Integer> receita = new HashMap<>();
        receita.put("Farinha", 300);
        receita.put("Açúcar", 100);

        kitchen.cookRecipe(receita);

        assertEquals(200, kitchen.getIngredientAmount("Farinha"));
        assertEquals(100, kitchen.getIngredientAmount("Açúcar"));
    }

    @Test
    public void testCozinharReceitaComIngredienteFaltando() {
        Kitchen kitchen = new Kitchen();
        kitchen.addIngredient("Farinha", 100);

        Map<String, Integer> receita = new HashMap<>();
        receita.put("Farinha", 200);

        assertThrows(IllegalArgumentException.class, () -> kitchen.cookRecipe(receita));
    }

    @Test
    public void testCozinharReceitaSemNenhumIngredienteDisponivel() {
        Kitchen kitchen = new Kitchen();

        Map<String, Integer> receita = new HashMap<>();
        receita.put("Chocolate", 1);

        assertThrows(IllegalArgumentException.class, () -> kitchen.cookRecipe(receita));
    }

    @Test
    public void testCookFailRemovesNoIngredients() {
        Kitchen kitchen = new Kitchen();
        kitchen.addIngredient("tofu", 400);
        kitchen.addIngredient("soy sauce", 50);
        kitchen.addIngredient("rice", 10);
        kitchen.addIngredient("onion", 1);

