import org.junit.Test;
import static org.junit.Assert.*;

/* For assertions you can use:
 - assertTrue
 - assertFalse
 - assertEquals
 - assertNotEquals
 - assertArrayEquals
 - assertThrows
 - assertNull
 - assertNotNull
 */

public class KitchenTest {

    @Test
    public void test() {
        Kitchen kitchen = new Kitchen();

        // Teste 1: Ingredientes inexistentes devem devolver 0
        assertEquals(0, kitchen.getIngredientAmount("flour"));

        // Teste 2: Adicionar um ingrediente novo e atualizar um existente
        kitchen.addIngredient("flour", 5);
        assertEquals(5, kitchen.getIngredientAmount("flour"));

        kitchen.addIngredient("flour", 3);
        assertEquals(8, kitchen.getIngredientAmount("flour")); // 5 + 3

        // Teste 3: Remover um ingrediente com sucesso
        kitchen.removeIngredient("flour", 2);
        assertEquals(6, kitchen.getIngredientAmount("flour")); // 8 - 2

        // Teste 4: Exceção ao tentar remover mais do que o que existe
        assertThrows(IllegalArgumentException.class, () -> {
            kitchen.removeIngredient("flour", 10);
        });

        // Adicionar mais ingredientes para o teste da receita
        kitchen.addIngredient("sugar", 5);

        // Teste 5: Cozinhar uma receita com sucesso
        Map<String, Integer> cakeRecipe = new HashMap<>();
        cakeRecipe.put("flour", 4);
        cakeRecipe.put("sugar", 2);

        kitchen.cookRecipe(cakeRecipe);

        // Verificar se os ingredientes foram descontados corretamente
        assertEquals(2, kitchen.getIngredientAmount("flour")); // 6 - 4
        assertEquals(3, kitchen.getIngredientAmount("sugar")); // 5 - 2

        // Teste 6: Tentar cozinhar uma receita sem ingredientes suficientes
        Map<String, Integer> impossibleRecipe = new HashMap<>();
        impossibleRecipe.put("flour", 10); // Falta farinha (só tem 2)
        impossibleRecipe.put("sugar", 1);  // Tem açúcar suficiente

        assertThrows(IllegalArgumentException.class, () -> {
            kitchen.cookRecipe(impossibleRecipe);
        });

        // Verificar se a cozinha manteve as quantidades intactas após a falha da receita
        assertEquals(2, kitchen.getIngredientAmount("flour"));
        assertEquals(3, kitchen.getIngredientAmount("sugar"));
    }

}
