  "sourceCode": "import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

/* For assertions you can use:
 - assertTrue
 - assertFalse
 - assertEquals
 - assertNotEquals
 - assertArrayEquals
 - assertThrows
 - assertNull
 - assertNotNull
 */

public class GreenHouseTest {

    @Test
    public void testPlantSetsGrowingState() {
        GreenHouse gh = new GreenHouse(3);
        gh.plant(0);
        assertEquals("Planting should set state to GROWING", GreenHouse.Plant.GROWING, gh.getPlantInfo()[0]);
    }

    @Test
    public void testWaterSetsReadyState() {
        GreenHouse gh = new GreenHouse(3);
        gh.plant(0);
        gh.water(0);
        assertEquals("Watering a GROWING plant should set it to READY", GreenHouse.Plant.READY, gh.getPlantInfo()[0]);
    }

    @Test
    public void testHarvestSetsEmptyState() {
        GreenHouse gh = new GreenHouse(3);
        gh.plant(1);
        gh.water(1);
        gh.harvest(1);
        assertEquals("Harvesting a READY plant should set it back to EMPTY", GreenHouse.Plant.EMPTY, gh.getPlantInfo()[1]);
    }

    @Test
    public void testAutomatic() {
        GreenHouse greenhouse = new GreenHouse(3);
        greenhouse.setPlantInfo(new GreenHouse.Plant[] {
                GreenHouse.Plant.DEAD,
                GreenHouse.Plant.GROWING,
                GreenHouse.Plant.EMPTY,
                GreenHouse.Plant.READY
        });
        greenhouse.automatic();
        assertArrayEquals(new GreenHouse.Plant[] {
                GreenHouse.Plant.EMPTY,
                GreenHouse.Plant.READY,
                GreenHouse.Plant.GROWING,
                GreenHouse.Plant.EMPTY
        }, greenhouse.getPlantInfo());
    }

}
