  "sourceCode": "import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

/* For assertions you can use:
 - assertTrue
 - assertFalse
 - assertEquals
 - assertNotEquals
 - assertArrayEquals
 - assertThrows
 - assertNull
 - assertNotNull
 */

public class GreenHouseTest {

    @Test
    public void testCicloDeVidaDeUmaPlantaComSucesso() {
        GreenHouse gh = new GreenHouse(1);

        // 1. Plantar -> Deve ir para GROWING
        gh.plant(0);
        assertEquals(GreenHouse.Plant.GROWING, gh.getPlantInfo()[0]);

        // 2. Regar -> Deve ir para READY
        gh.water(0);
        assertEquals(GreenHouse.Plant.READY, gh.getPlantInfo()[0]);

        // 3. Colher -> Deve voltar para EMPTY
        gh.harvest(0);
        assertEquals(GreenHouse.Plant.EMPTY, gh.getPlantInfo()[0]);
    }

    @Test
    public void testAutomatic() {
        GreenHouse greenhouse = new GreenHouse(3);
        greenhouse.setPlantInfo(new GreenHouse.Plant[] {
                GreenHouse.Plant.DEAD,
                GreenHouse.Plant.GROWING,
                GreenHouse.Plant.EMPTY,
                GreenHouse.Plant.READY
        });
        greenhouse.automatic();
        assertArrayEquals(new GreenHouse.Plant[] {
                GreenHouse.Plant.EMPTY,
                GreenHouse.Plant.READY,
                GreenHouse.Plant.GROWING,
                GreenHouse.Plant.EMPTY
        }, greenhouse.getPlantInfo());
    }

}
