  "sourceCode": "import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

/* For assertions you can use:
 - assertTrue
 - assertFalse
 - assertEquals
 - assertNotEquals
 - assertArrayEquals
 - assertThrows
 - assertNull
 - assertNotNull
 */

public class GreenHouseTest {

    @Test
    public void testConstructorAndInitialState() {
        GreenHouse gh = new GreenHouse(3);
        GreenHouse.Plant[] plants = gh.getPlantInfo();

        assertEquals(3, plants.length);
        assertEquals(GreenHouse.Plant.EMPTY, plants[0]);
        assertEquals(GreenHouse.Plant.EMPTY, plants[1]);
        assertEquals(GreenHouse.Plant.EMPTY, plants[2]);
    }

    @Test
    public void testPlantSuccess() {
        GreenHouse gh = new GreenHouse(1);
        gh.plant(0);

        assertEquals("A planta deve estar GROWING após ser plantada.", 
                     GreenHouse.Plant.GROWING, gh.getPlantInfo()[0]);
    }

    @Test
    public void testPlantInvalidIndex() {
        GreenHouse gh = new GreenHouse(2);

        assertThrows("Deve lançar exceção para índice negativo.",
                     IllegalArgumentException.class, () -> gh.plant(-1));

        assertThrows("Deve lançar exceção para índice fora do limite.",
                     IllegalArgumentException.class, () -> gh.plant(2));
    }

    @Test
    public void testPlantAlreadyOccupied() {
        GreenHouse gh = new GreenHouse(1);
        gh.plant(0);

        assertThrows("Deve lançar exceção ao tentar plantar onde já existe uma planta.",
                     IllegalStateException.class, () -> gh.plant(0));
    }

    @Test
    public void testWaterSuccess() {
        GreenHouse gh = new GreenHouse(1);
        gh.plant(0); 
        gh.water(0); 

        assertEquals("A planta deve estar READY após ser regada.", 
                     GreenHouse.Plant.READY, gh.getPlantInfo()[0]);
    }

    @Test
    public void testWaterDoesNothingIfNotGrowing() {
        GreenHouse gh = new GreenHouse(1);
        gh.water(0);

        assertEquals("A planta deve continuar EMPTY se for regada antes de nascer.", 
                     GreenHouse.Plant.EMPTY, gh.getPlantInfo()[0]);
    }

    @Test
    public void testWaterInvalidIndex() {
        GreenHouse gh = new GreenHouse(1);
        assertThrows(IllegalArgumentException.class, () -> gh.water(5));
    }

    @Test
    public void testHarvestSuccess() {
        GreenHouse gh = new GreenHouse(1);
        gh.plant(0);
        gh.water(0); 
        gh.harvest(0);

        assertEquals("O espaço deve ficar EMPTY após a colheita.", 
                     GreenHouse.Plant.EMPTY, gh.getPlantInfo()[0]);
    }

    @Test
    public void testHarvestNotReady() {
        GreenHouse gh = new GreenHouse(1);
        gh.plant(0);

        assertThrows("Deve lançar exceção ao colher uma planta que não está READY.",
                     IllegalStateException.class, () -> gh.harvest(0));
    }

    @Test
    public void testHarvestInvalidIndex() {
        GreenHouse gh = new GreenHouse(1);
        assertThrows(IllegalArgumentException.class, () -> gh.harvest(-5));
    }

    @Test
    public void testAutomatic() {
        GreenHouse greenhouse = new GreenHouse(3);
        greenhouse.setPlantInfo(new GreenHouse.Plant[] {
                GreenHouse.Plant.DEAD,
                GreenHouse.Plant.GROWING,
                GreenHouse.Plant.EMPTY,
                GreenHouse.Plant.READY
        });
        greenhouse.automatic();
        assertArrayEquals(new GreenHouse.Plant[] {
                GreenHouse.Plant.EMPTY,
                GreenHouse.Plant.READY,
                GreenHouse.Plant.GROWING,
                GreenHouse.Plant.EMPTY
        }, greenhouse.getPlantInfo());
    }

}
