    "className": "GreenHouseTest",
    "sourceCode": "import java.util.*;\nimport org.junit.Test;\nimport static org.junit.Assert.*;\n\n/* For assertions you can use:\n - assertTrue\n - assertFalse\n - assertEquals\n - assertNotEquals\n - assertArrayEquals\n - assertThrows\n - assertNull\n - assertNotNull\n */\n\npublic class GreenHouseTest {\n\n    @Test\n    public void test() {\n        // Teste 1: Inicializa\u00e7\u00e3o\n        GreenHouse gh = new GreenHouse(3);\n        GreenHouse.Plant[] plants = gh.getPlantInfo();\n        assertEquals(GreenHouse.Plant.EMPTY, plants[0]);\n        assertEquals(GreenHouse.Plant.EMPTY, plants[1]);\n        assertEquals(GreenHouse.Plant.EMPTY, plants[2]);\n\n        // Teste 2: Plantar com sucesso\n        gh.plant(0);\n        assertEquals(GreenHouse.Plant.GROWING, gh.getPlantInfo()[0]);\n\n        // Teste 3: Exce\u00e7\u00e3o ao tentar plantar onde j\u00e1 existe planta\n        assertThrows(IllegalStateException.class, () -> {\n            gh.plant(0);\n        });\n\n        // Teste 4: Regar para mudar para READY\n        gh.water(0);\n        assertEquals(GreenHouse.Plant.READY, gh.getPlantInfo()[0]);\n\n        // Teste 5: Exce\u00e7\u00e3o ao tentar colher uma planta que n\u00e3o est\u00e1 READY (ex: slot 1 est\u00e1 EMPTY)\n        assertThrows(IllegalStateException.class, () -> {\n            gh.harvest(1);\n        });\n\n        // Teste 6: Colher com sucesso\n        gh.harvest(0);\n        assertEquals(GreenHouse.Plant.EMPTY, gh.getPlantInfo()[0]);\n\n        // Teste 7: Exce\u00e7\u00f5es de limites de \u00edndices (negativos ou maiores que a capacidade)\n        assertThrows(IllegalArgumentException.class, () -> {\n            gh.plant(-1);\n        });\n        assertThrows(IllegalArgumentException.class, () -> {\n            gh.water(5);\n        });\n\n        // Teste 8: Validar o sistema Autom\u00e1tico (testa as 4 transi\u00e7\u00f5es de estado)\n        GreenHouse ghAuto = new GreenHouse(4);\n        GreenHouse.Plant[] initialStates = {\n            GreenHouse.Plant.EMPTY,\n            GreenHouse.Plant.GROWING,\n            GreenHouse.Plant.READY,\n            GreenHouse.Plant.DEAD\n        };\n        ghAuto.setPlantInfo(initialStates);\n        \n        ghAuto.automatic();\n        \n        GreenHouse.Plant[] finalStates = ghAuto.getPlantInfo();\n        assertEquals(GreenHouse.Plant.GROWING, finalStates[0]); // EMPTY passou a GROWING\n        assertEquals(GreenHouse.Plant.READY, finalStates[1]);   // GROWING passou a READY\n        assertEquals(GreenHouse.Plant.EMPTY, finalStates[2]);   // READY foi colhida e passou a EMPTY\n        assertEquals(GreenHouse.Plant.EMPTY, finalStates[3]);   // DEAD foi limpa e passou a EMPTY\n    }\n\n}\n",
