    "sourceCode": "import java.util.*;\nimport org.junit.Test;\nimport static org.junit.Assert.*;\n\n/* For assertions you can use:\n - assertTrue\n - assertFalse\n - assertEquals\n - assertNotEquals\n - assertArrayEquals\n - assertThrows\n - assertNull\n - assertNotNull\n */\n\npublic class KitchenTest {\n\n    @Test\n    public void testAddAndGetIngredient() {\n        Kitchen kitchen = new Kitchen();\n        \n        // Verify a missing ingredient defaults to 0\n        assertEquals(0, kitchen.getIngredientAmount(\"Tomato\"));\n        \n        // Verify adding a brand new ingredient works\n        kitchen.addIngredient(\"Tomato\", 5);\n        assertEquals(5, kitchen.getIngredientAmount(\"Tomato\"));\n        \n        // Verify adding to an existing inventory item accumulates correctly\n        kitchen.addIngredient(\"Tomato\", 3);\n        assertEquals(8, kitchen.getIngredientAmount(\"Tomato\"));\n    }\n\n    @Test\n    public void testRemoveIngredientSuccess() {\n        Kitchen kitchen = new Kitchen();\n        kitchen.addIngredient(\"Cheese\", 10);\n        \n        // Verify successful deduction\n        kitchen.removeIngredient(\"Cheese\", 4);\n        assertEquals(6, kitchen.getIngredientAmount(\"Cheese\"));\n    }\n\n    @Test\n    public void testRemoveIngredientInsufficient() {\n        Kitchen kitchen = new Kitchen();\n        kitchen.addIngredient(\"Cheese\", 3);\n        \n        // Verify an exception is thrown if we try to take more than available\n        assertThrows(IllegalArgumentException.class, () -> {\n            kitchen.removeIngredient(\"Cheese\", 5);\n        });\n    }\n\n    @Test\n    public void testCookRecipeSuccess() {\n        Kitchen kitchen = new Kitchen();\n        kitchen.addIngredient(\"Flour\", 500);\n        kitchen.addIngredient(\"Egg\", 3);\n        \n        Map<String, Integer> recipe = new HashMap<>();\n        recipe.put(\"Flour\", 200);\n        recipe.put(\"Egg\", 2);\n        \n        // Verify cooking successfully processes all ingredients\n        kitchen.cookRecipe(recipe);\n        \n        assertEquals(300, kitchen.getIngredientAmount(\"Flour\"));\n        assertEquals(1, kitchen.getIngredientAmount(\"Egg\"));\n    }\n\n    @Test\n    public void testCookRecipeInsufficientIngredients() {\n        Kitchen kitchen = new Kitchen();\n        kitchen.addIngredient(\"Flour\", 100); // Insufficient (needs 200)\n        kitchen.addIngredient(\"Egg\", 5);     // Sufficient (needs 2)\n        \n        Map<String, Integer> recipe = new HashMap<>();\n        recipe.put(\"Flour\", 200);\n        recipe.put(\"Egg\", 2);\n        \n        // Verify exception is thrown during validation phase\n        assertThrows(IllegalArgumentException.class, () -> {\n            kitchen.cookRecipe(recipe);\n        });\n        \n        // CRITICAL branch check: Verify that NO ingredients were modified \n        // because the validation step is supposed to fail before cooking starts.\n        assertEquals(100, kitchen.getIngredientAmount(\"Flour\"));\n        assertEquals(5, kitchen.getIngredientAmount(\"Egg\"));\n    }\n\n}\n",
