public class KitchenTest {

@Test
public void test() {
    Kitchen kitchen = new Kitchen();

    assertEquals(0, kitchen.getIngredientAmount("flour"));

    kitchen.addIngredient("flour", 5);
    assertEquals(5, kitchen.getIngredientAmount("flour"));

    kitchen.addIngredient("flour", 3);
    assertEquals(8, kitchen.getIngredientAmount("flour"));

    kitchen.removeIngredient("flour", 2);
    assertEquals(6, kitchen.getIngredientAmount("flour"));

    assertThrows(IllegalArgumentException.class, () -> kitchen.removeIngredient("flour", 10));
    assertEquals(6, kitchen.getIngredientAmount("flour"));

    kitchen.addIngredient("egg", 4);

    Map<String, Integer> recipe = new HashMap<>();
    recipe.put("flour", 3);
    recipe.put("egg", 2);

    kitchen.cookRecipe(recipe);

    assertEquals(3, kitchen.getIngredientAmount("flour"));
    assertEquals(2, kitchen.getIngredientAmount("egg"));

    Map<String, Integer> impossibleRecipe = new HashMap<>();
    impossibleRecipe.put("flour", 2);
    impossibleRecipe.put("milk", 1);

    assertThrows(IllegalArgumentException.class, () -> kitchen.cookRecipe(impossibleRecipe));

    assertEquals(3, kitchen.getIngredientAmount("flour"));
    assertEquals(0, kitchen.getIngredientAmount("milk"));
}
}
