  "sourceCode": "import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

/* For assertions you can use:
 - assertTrue
 - assertFalse
 - assertEquals
 - assertNotEquals
 - assertArrayEquals
 - assertThrows
 - assertNull
 - assertNotNull
 */

public class GreenHouseTest {

    @Test
    public void testCicloBasicoDePlatacao() {
        GreenHouse gh = new GreenHouse(2);

        gh.plant(0);
        assertEquals(GreenHouse.Plant.GROWING, gh.getPlantInfo()[0]);

        gh.water(0);
        assertEquals(GreenHouse.Plant.READY, gh.getPlantInfo()[0]);

        gh.harvest(0);
        assertEquals(GreenHouse.Plant.EMPTY, gh.getPlantInfo()[0]);
    }

    @Test
    public void testModoAutomatico() {
        GreenHouse gh = new GreenHouse(4);

        GreenHouse.Plant[] estadoInicial = {
            GreenHouse.Plant.EMPTY,
            GreenHouse.Plant.GROWING,
            GreenHouse.Plant.READY,
            GreenHouse.Plant.DEAD
        };
        gh.setPlantInfo(estadoInicial);

        gh.automatic();

        GreenHouse.Plant[] estadoEsperado = {
            GreenHouse.Plant.GROWING,
            GreenHouse.Plant.READY,
            GreenHouse.Plant.EMPTY,
            GreenHouse.Plant.EMPTY
        };

        assertArrayEquals(estadoEsperado, gh.getPlantInfo());
    }

    @Test
    public void testExcecoesDeIndiceInvalido() {
        GreenHouse gh = new GreenHouse(1);

        assertThrows(IllegalArgumentException.class, () -> gh.plant(-1));
        assertThrows(IllegalArgumentException.class, () -> gh.plant(1));
        assertThrows(IllegalArgumentException.class, () -> gh.water(1));
        assertThrows(IllegalArgumentException.class, () -> gh.harvest(1));
    }

    @Test
    public void testExcecoesDeEstadoInvalido() {
        GreenHouse gh = new GreenHouse(1);

        assertThrows(IllegalStateException.class, () -> gh.harvest(0));

        gh.plant(0);
        assertThrows(IllegalStateException.class, () -> gh.plant(0));
    }

}
