public class EngineTest {

    @Test
    public void test() {
        Engine engine = new Engine();

        // Teste 1: O rácio é 78/22, logo 22 de CH4 deve precisar de exatamente 78 de O2
        assertEquals(78.0, engine.getO2(22.0), 0.0001);

        // Teste 2: Se não houver CH4 (0), também não deve precisar de O2
        assertEquals(0.0, engine.getO2(0.0), 0.0001);

        // Teste 3: Ativar o modo shutdown
        engine.shutdown();

        // Teste 4: Após o shutdown, o motor corta o oxigénio, logo tem de devolver 0
        assertEquals(0.0, engine.getO2(22.0), 0.0001);
        assertEquals(0.0, engine.getO2(100.0), 0.0001);
    }
}
