    "sourceCode": "import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

/* For assertions you can use:
 - assertTrue
 - assertFalse
 - assertEquals
 - assertNotEquals
 - assertArrayEquals
 - assertThrows
 - assertNull
 - assertNotNull
 */

public class GreenHouseTest {

    @Test
public void test() {
    GreenHouse greenhouse = new GreenHouse(4);

    assertArrayEquals(
        new GreenHouse.Plant[] {
            GreenHouse.Plant.EMPTY,
            GreenHouse.Plant.EMPTY,
            GreenHouse.Plant.EMPTY,
            GreenHouse.Plant.EMPTY
        },
        greenhouse.getPlantInfo()
    );

    greenhouse.plant(0);
    assertEquals(GreenHouse.Plant.GROWING, greenhouse.getPlantInfo()[0]);

    greenhouse.water(0);
    assertEquals(GreenHouse.Plant.READY, greenhouse.getPlantInfo()[0]);

    greenhouse.harvest(0);
    assertEquals(GreenHouse.Plant.EMPTY, greenhouse.getPlantInfo()[0]);

    greenhouse.plant(1);
    assertThrows(IllegalStateException.class, () -> greenhouse.plant(1));

    greenhouse.plant(2);
    assertThrows(IllegalStateException.class, () -> greenhouse.harvest(2));

    assertThrows(IllegalArgumentException.class, () -> greenhouse.plant(-1));
    assertThrows(IllegalArgumentException.class, () -> greenhouse.plant(4));
    assertThrows(IllegalArgumentException.class, () -> greenhouse.water(-1));
    assertThrows(IllegalArgumentException.class, () -> greenhouse.water(4));
    assertThrows(IllegalArgumentException.class, () -> greenhouse.harvest(-1));
    assertThrows(IllegalArgumentException.class, () -> greenhouse.harvest(4));

    greenhouse.setPlantInfo(new GreenHouse.Plant[] {
        GreenHouse.Plant.GROWING,
        GreenHouse.Plant.READY,
        GreenHouse.Plant.DEAD,
        GreenHouse.Plant.EMPTY
    });

    greenhouse.automatic();

    assertArrayEquals(
        new GreenHouse.Plant[] {
            GreenHouse.Plant.READY,
            GreenHouse.Plant.EMPTY,
            GreenHouse.Plant.EMPTY,
            GreenHouse.Plant.GROWING
        },
        greenhouse.getPlantInfo()
    );
}

}
