import org.junit.Test;
import static org.junit.Assert.*;

/* For assertions you can use:
 - assertTrue
 - assertFalse
 - assertEquals
 - assertNotEquals
 - assertArrayEquals
 - assertThrows
 - assertNull
 - assertNotNull
 */

public class GreenHouseTest {

    @Test
    public void testInitialization() {
        GreenHouse gh = new GreenHouse(3);
        GreenHouse.Plant[] plants = gh.getPlantInfo();

        assertEquals("Capacity should be 3", 3, plants.length);
        for (GreenHouse.Plant p : plants) {
            assertEquals("All plants should initially be EMPTY", GreenHouse.Plant.EMPTY, p);
        }
    }

    @Test
    public void testPlanting() {
        GreenHouse gh = new GreenHouse(1);

        // Normal planting
        gh.plant(0);
        assertEquals("Plant should be GROWING after planting", GreenHouse.Plant.GROWING, gh.getPlantInfo()[0]);

        // Exception: Already planted
        assertThrows("Should throw IllegalStateException if already planted", 
            IllegalStateException.class, () -> gh.plant(0));

        // Exception: Out of bounds
        assertThrows(IllegalArgumentException.class, () -> gh.plant(-1));
        assertThrows(IllegalArgumentException.class, () -> gh.plant(1));
    }

    @Test
    public void testWatering() {
        GreenHouse gh = new GreenHouse(2);
        gh.plant(0);

        // Normal watering
        gh.water(0);
        assertEquals("Plant should be READY after watering", GreenHouse.Plant.READY, gh.getPlantInfo()[0]);

        // Watering a plant that isn't GROWING (should safely do nothing based on your if-condition)
        gh.water(1);
        assertEquals("Empty slot should remain EMPTY when watered", GreenHouse.Plant.EMPTY, gh.getPlantInfo()[1]);

        // Exception: Out of bounds
        assertThrows(IllegalArgumentException.class, () -> gh.water(-1));
        assertThrows(IllegalArgumentException.class, () -> gh.water(2));
    }

    @Test
    public void testHarvesting() {
        GreenHouse gh = new GreenHouse(1);

        // Setup a READY plant
        gh.plant(0);
        gh.water(0);

        // Normal harvest
        gh.harvest(0);
        assertEquals("Slot should be EMPTY after harvest", GreenHouse.Plant.EMPTY, gh.getPlantInfo()[0]);

        // Exception: Harvesting an unready/empty plant
        assertThrows("Should throw IllegalStateException if not READY", 
            IllegalStateException.class, () -> gh.harvest(0));

        // Exception: Out of bounds
        assertThrows(IllegalArgumentException.class, () -> gh.harvest(-1));
        assertThrows(IllegalArgumentException.class, () -> gh.harvest(1));
    }

    @Test
    public void testAutomaticSystem() {
        GreenHouse gh = new GreenHouse(4);

        // Use setPlantInfo to artificially set up all 4 possible states
        GreenHouse.Plant[] testBed = {
            GreenHouse.Plant.EMPTY,
            GreenHouse.Plant.GROWING,
            GreenHouse.Plant.READY,
            GreenHouse.Plant.DEAD
        };
        gh.setPlantInfo(testBed);

        // Run the automation
        gh.automatic();

        GreenHouse.Plant[] result = gh.getPlantInfo();

        // Verify all 4 switch cases triggered the correct state transitions
        assertEquals("EMPTY should become GROWING", GreenHouse.Plant.GROWING, result[0]);
        assertEquals("GROWING should become READY", GreenHouse.Plant.READY, result[1]);
        assertEquals("READY should become EMPTY", GreenHouse.Plant.EMPTY, result[2]);
        assertEquals("DEAD should be cleared to EMPTY", GreenHouse.Plant.EMPTY, result[3]);
    }
}
