    "sourceCode": "import java.util.*;\nimport org.junit.Test;\nimport static org.junit.Assert.*;\n\n/* For assertions you can use:\n - assertTrue\n - assertFalse\n - assertEquals\n - assertNotEquals\n - assertArrayEquals\n - assertThrows\n - assertNull\n - assertNotNull\n */\n\npublic class CryoSleepTest {\n\n    @Test\n    public void testCicloDeVidaCompletoEContagemDeDias() {\n        // Cen\u00e1rio com 3 dias para garantir que decrementa corretamente a cada passo\n        CryoSleep pod = new CryoSleep(3);\n        \n        // Estado Inicial\n        assertTrue(\"Devia iniciar congelado para 3 dias\", pod.isFrozen());\n\n        // Passou o Dia 1 -> (3 -> 2 dias restantes)\n        pod.dayPassed();\n        assertTrue(\"Devia continuar congelado ap\u00f3s o primeiro dia\", pod.isFrozen());\n\n        // Passou o Dia 2 -> (2 -> 1 dia restante)\n        pod.dayPassed();\n        assertTrue(\"Devia continuar congelado quando resta 1 dia\", pod.isFrozen());\n\n        // Passou o Dia 3 -> (1 -> 0 dias restantes) -> Deve descongelar exatamente aqui\n        pod.dayPassed();\n        assertFalse(\"Devia descongelar exatamente quando os dias chegam a 0\", pod.isFrozen());\n        \n        // Passou mais um dia com o tempo j\u00e1 esgotado\n        pod.dayPassed();\n        assertFalse(\"Deve permanecer descongelado\", pod.isFrozen());\n    }\n\n    @Test\n    public void testLimiteComExatamenteUmDia() {\n        // Caso cr\u00edtico: apenas 1 dia\n        CryoSleep pod = new CryoSleep(1);\n        assertTrue(\"Deve iniciar congelado com 1 dia\", pod.isFrozen());\n        \n        pod.dayPassed();\n        assertFalse(\"Deve descongelar imediatamente ap\u00f3s 1 dia passar\", pod.isFrozen());\n    }\n\n    @Test\n    public void testInicializacaoComZeroDias() {\n        CryoSleep pod = new CryoSleep(0);\n        assertFalse(\"N\u00e3o deve congelar com 0 dias\", pod.isFrozen());\n\n        // Garante que chamar o m\u00e9todo n\u00e3o altera o estado incorretamente\n        pod.dayPassed();\n        assertFalse(\"Deve continuar descongelado\", pod.isFrozen());\n    }\n\n    @Test\n    public void testInicializacaoComDiasNegativos() {\n        CryoSleep pod = new CryoSleep(-1);\n        assertFalse(\"N\u00e3o deve congelar com dias negativos\", pod.isFrozen());\n        \n        CryoSleep podNegativoGrande = new CryoSleep(-999);\n        assertFalse(\"N\u00e3o deve congelar com grandes valores negativos\", podNegativoGrande.isFrozen());\n    }\n}\n",
