 - assertNotEquals
 - assertArrayEquals
 - assertThrows
 - assertNull
 - assertNotNull
 */

public class CryoSleepTest {

    @Test
    public void testStartsFrozen() {
        CryoSleep cs = new CryoSleep(3);
        assertTrue(cs.isFrozen());
    }

    @Test
    public void testEndsAfterDaysPass() {
        CryoSleep cs = new CryoSleep(2);

        cs.dayPassed();
        cs.dayPassed();
        cs.dayPassed();

        assertFalse(cs.isFrozen());
    }

    @Test
    public void testZeroDaysNotFrozen() {
        CryoSleep cs = new CryoSleep(0);
        assertFalse(cs.isFrozen());
    }

    @Test
    public void testWakeUp() {
        CryoSleep cryo = new CryoSleep(3);

        cryo.dayPassed();
        cryo.dayPassed();
        cryo.dayPassed();
        cryo.dayPassed();

        assertFalse(cryo.isFrozen());
    }

    @Test
    public void testWakeUp() {
        CryoSleep cryo = new CryoSleep(3);
        cryo.dayPassed();
        cryo.dayPassed();
        cryo.dayPassed();
        assertFalse(cryo.isFrozen());
    }

}
