    @Test
    public void testCalculoProporcaoO2() {
        Engine engine = new Engine();
        double ch4 = 22.0;
        double esperadoO2 = 78.0;
        assertEquals(esperadoO2, engine.getO2(ch4), 0.0001);
    }

    @Test
    public void testFuncionamentoComOutrosValores() {
        Engine engine = new Engine();
        assertEquals(0.0, engine.getO2(0.0), 0.0001);

