    public void testComportamentoEmShutdown() {
        Engine engine = new Engine();
        engine.shutdown();
        assertEquals(0.0, engine.getO2(22.0), 0.0001);
        assertEquals(0.0, engine.getO2(500.0), 0.0001);
    }

}
