import org.junit.Test;
import static org.junit.Assert.*;

/* For assertions you can use:
 - assertTrue
 - assertFalse
 - assertEquals
 - assertNotEquals
 - assertArrayEquals
 - assertThrows
 - assertNull
 - assertNotNull
 */

public class CryoSleepTest {

    private boolean isFrozen;

    public void CryoSleep(int forDays) {
        daysRemaining = forDays;
        isFrozen = forDays > 0;

        System.out.println("CryoSleep started for " + daysRemaining + " days");
    }

    public void dayPassed() {
        if (isFrozen) {
            daysRemaining--;
            if (daysRemaining <= 0) {
                isFrozen = false;
                System.out.println("CryoSleep ended");
            }
        } else {
            System.out.println("CryoSleep is already over");
        }
    }

    public boolean isFrozen() {
        return isFrozen;
    }


    @Test
    public void test() {
        int daysRemaining;
        int daysRemaining;
        int dayPassed = 0;
        int daysCounter = 0;
        CryoSleep(10);
        while(isFrozen()){
            dayPassed();
            daysCounter++;
            assertTrue(daysRemaining == 10 - daysCounter);
        }
    }
}
