        assertEquals(78.0, O2, 0.000001);
    }

    @Test
    public void testO2RatioForOneCH4() {
        Engine engine = new Engine();

        double o2 = engine.getO2(1);

        assertEquals(78.0 / 22.0, o2, 0.000001);
    }

    @Test
    public void testZeroCH4NeedsZeroO2() {
        Engine engine = new Engine();

        double o2 = engine.getO2(0);

        assertEquals(0.0, o2, 0.000001);
    }

    @Test
    public void testShutdownReturnsZeroO2() {
        Engine engine = new Engine();

        engine.shutdown();

        double o2 = engine.getO2(22);

        assertEquals(0.0, o2, 0.000001);
    }

    @Test
    public void testShutdownStaysActive() {
        Engine engine = new Engine();

        engine.shutdown();

        assertEquals(0.0, engine.getO2(22), 0.000001);
        assertEquals(0.0, engine.getO2(100), 0.000001);
    }

}
