    public void test() {
        int daysRemaining;
        int dayPassed = 0;
        int daysCounter = 0;
        CryoSleep(10);
        while(isFrozen()){
            dayPassed();
            daysCounter++;
            assertTrue(daysRemaining == 10 - daysCounter);
        }
    }
}
