public class CryoSleepTest {

    @Test
    public void testInitialStateFrozen() {
       CryoSleep sleep = new CryoSleep(5);
       assertTrue("O CryoSleep deve estar congelado inicialmente para dias positivos", sleep.isFrozen());
    }

    @Test
    public void testInitialStateNotFrozen() {
        CryoSleep zeroSleep = new CryoSleep(0);
        assertFalse("O CryoSleep não deve estar congelado inicialmente para zero dias", zeroSleep.isFrozen());

        CryoSleep negativeSleep = new CryoSleep(-3);
        assertFalse("O CryoSleep não deve estar congelado inicialmente para dias negativos", negativeSleep.isFrozen());
    }

    @Test
    public void testDayPassedThawsWhenZero() {
        CryoSleep sleep = new CryoSleep(1);
        sleep.dayPassed();
        assertFalse("O CryoSleep deve descongelar após os dias exatos necessários terem passado", sleep.isFrozen());
    }

    @Test
    public void testMultipleDays() {
        CryoSleep sleep = new CryoSleep(3);

        sleep.dayPassed();
        assertTrue("Ainda deve estar congelado após 1 dia.", sleep.isFrozen());

        sleep.dayPassed();
        assertTrue("Ainda deve estar congelado após 2 dias.", sleep.isFrozen());

        sleep.dayPassed();
        assertFalse("Deve descongelar após o 3º dia.", sleep.isFrozen());
    }

}
