    @Test
    public void testInitializationWithPositiveDays() {
        CryoSleep sleep = new CryoSleep(5);
        assertTrue("Should be frozen when initialized with positive days.", sleep.isFrozen());
    }

    @Test
    public void testInitializationWithZeroDays() {
        CryoSleep sleep = new CryoSleep(0);
        assertFalse("Should not be frozen when initialized with 0 days.", sleep.isFrozen());
    }

    @Test
    public void testInitializationWithNegativeDays() {
        CryoSleep sleep = new CryoSleep(-2);
        assertFalse("Should not be frozen when initialized with negative days.", sleep.isFrozen());
    }

    @Test
    public void testDayPassedDecrements() {
        CryoSleep sleep = new CryoSleep(2);
        assertTrue(sleep.isFrozen());

        sleep.dayPassed();
        assertTrue("Should still be frozen after 1 day has passed.", sleep.isFrozen());

        sleep.dayPassed();
        assertFalse("Should thaw after all 2 days have passed.", sleep.isFrozen());
    }

}
