 */

public class CryoSleepTest {

    @Test
    public void startsFrozenWhenDaysArePositive() {
        CryoSleep cryo = new CryoSleep(3);

        assertTrue(cryo.isFrozen());
    }

    @Test
    public void startsNotFrozenWhenDaysAreZero() {
        CryoSleep cryo = new CryoSleep(0);

        assertFalse(cryo.isFrozen());
    }

    @Test
    public void staysFrozenBeforeLastDay() {
        CryoSleep cryo = new CryoSleep(2);

        cryo.dayPassed();

        assertTrue(cryo.isFrozen());
    }

    @Test
    public void unfreezesAfterAllDaysPass() {
        CryoSleep cryo = new CryoSleep(2);

        cryo.dayPassed();
        cryo.dayPassed();

        assertFalse(cryo.isFrozen());
    }

    @Test
    public void staysNotFrozenIfDayPassedAfterCryoSleepEnded() {
        CryoSleep cryo = new CryoSleep(1);

        cryo.dayPassed();
        cryo.dayPassed();

        assertFalse(cryo.isFrozen());
    }

    @Test
    public void negativeDaysDoNotFreeze() {
        CryoSleep cryo = new CryoSleep(-2);

        assertFalse(cryo.isFrozen());
    }
}
