   @Test
    public void testNormalCryoSleepDuration() {
        CryoSleep sleep = new CryoSleep(2);
        assertTrue("Should be frozen initially", sleep.isFrozen());

        sleep.dayPassed();
        assertTrue("Should still be frozen after 1 day", sleep.isFrozen());

        sleep.dayPassed();
        assertFalse("Should not be frozen after 2 days", sleep.isFrozen());
    }

    @Test
    public void testCryoSleepAlreadyOver() {
        // Initialize with 0 days so it's unfrozen from the start
        CryoSleep sleep = new CryoSleep(0);
        assertFalse("Should not be frozen with 0 days", sleep.isFrozen());

        // This will hit the 'else' block in dayPassed()
        sleep.dayPassed();
        assertFalse("Should remain unfrozen", sleep.isFrozen());
    }

    @Test
    public void testCryoSleepNegativeDays() {
        // Edge case: negative days
        CryoSleep sleep = new CryoSleep(-1);
        assertFalse("Should not be frozen with negative days", sleep.isFrozen());
    }


