 - assertThrows
 - assertNull
 - assertNotNull
 */

public class CryoSleepTest {

    @Test
    public void testCicloDeVidaPadraoDoCryoSleep() {
        // Arrange & Act: Inicia o criosono por 2 dias
        CryoSleep pod = new CryoSleep(2);

        // Assert: Deve estar congelado inicialmente
        assertTrue("O pod deve estar congelado no início", pod.isFrozen());

        // Act: Passa o primeiro dia
        pod.dayPassed();
        assertTrue("O pod ainda deve estar congelado após 1 dia", pod.isFrozen());

        // Act: Passa o segundo dia (último dia)
        pod.dayPassed();
        assertFalse("O pod deve descongelar após o término dos dias", pod.isFrozen());

        // Act: Tenta passar mais um dia com o processo já finalizado
        pod.dayPassed();
        assertFalse("O pod deve continuar descongelado", pod.isFrozen());
    }

    @Test
    public void testInicializacaoComZeroDias() {
        // Arrange & Act: Inicia o criosono com 0 dias
        CryoSleep pod = new CryoSleep(0);

        // Assert: Não deve estar congelado desde o início
        assertFalse("O pod não deve estar congelado se iniciado com 0 dias", pod.isFrozen());

        // Act & Assert: Passar um dia não deve congelá-lo
        pod.dayPassed();
        assertFalse("O pod deve continuar descongelado após dayPassed", pod.isFrozen());
    }

    @Test
    public void testInicializacaoComDiasNegativos() {
        // Arrange & Act: Inicia o criosono com -5 dias
        CryoSleep pod = new CryoSleep(-5);

        // Assert: Não deve estar congelado para valores negativos
        assertFalse("O pod não deve estar congelado se iniciado com dias negativos", pod.isFrozen());
    }

